38		public static void visitCodePoints(String str, IntConsumer visitor) {
39			int len = str.length();
40			int offset = 0;
41			while (offset < len) {
42				int codePoint = str.codePointAt(offset);
43				visitor.accept(codePoint);
44				offset += Character.charCount(codePoint);
45			}
46		}
47	
48		public String unescapeString(String str) {
49			int len = str.length();
50			if (len == 0) {
51				return "\"\"";
52			}
53			StringBuilder res = new StringBuilder();
54			res.append('"');
55			visitCodePoints(str, codePoint -> processCodePoint(codePoint, res));
56			res.append('"');
57			return res.toString();
58		}
59	
60		private void processCodePoint(int codePoint, StringBuilder res) {
61			String str = getSpecialStringForCodePoint(codePoint);
62			if (str != null) {
63				res.append(str);
64				return;
65			}
66			if (isEscapeNeededForCodePoint(codePoint)) {
67				res.append("\\u").append(String.format("%04x", codePoint));
68			} else {
69				res.appendCodePoint(codePoint);
70			}
71		}
72	
73		private boolean isEscapeNeededForCodePoint(int codePoint) {
74			if (codePoint < 32) {
75				return true;
76			}
77			if (codePoint < 127) {
78				return false;
79			}
80			if (escapeUnicode) {
81				return true;
82			}
83			return !NameMapper.isPrintableCodePoint(codePoint);
84		}
85	
86		/**
87		 * Represent single char the best way possible
88		 */
89		public String unescapeChar(char c, boolean explicitCast) {
90			if (c == '\'') {
91				return "'\\''";
92			}
93			String str = getSpecialStringForCodePoint(c);
94			if (str != null) {
95				return '\'' + str + '\'';
96			}
97			if (c >= 127 && escapeUnicode) {
98				return String.format("'\\u%04x'", (int) c);
99			}
100			if (NameMapper.isPrintableChar(c)) {
101				return "'" + c + '\'';
102			}
103			String intStr = Integer.toString(c);
104			return explicitCast ? "(char) " + intStr : intStr;
105		}
106	
107		public String unescapeChar(char ch) {
108			return unescapeChar(ch, false);
109		}
110	
111		@Nullable
112		private String getSpecialStringForCodePoint(int c) {
113			switch (c) {
114				case '\n':
115					return "\\n";
116				case '\r':
117					return "\\r";
118				case '\t':
119					return "\\t";
120				case '\b':
121					return "\\b";
122				case '\f':
123					return "\\f";
124				case '\'':
125					return "'";
126				case '"':
127					return "\\\"";
128				case '\\':
129					return "\\\\";
130	
131				default:
132					return null;
133			}
134		}
