136		public static String escape(String str) {
137			int len = str.length();
138			StringBuilder sb = new StringBuilder(len);
139			for (int i = 0; i < len; i++) {
140				char c = str.charAt(i);
141				switch (c) {
142					case '.':
143					case '/':
144					case ';':
145					case '$':
146					case ' ':
147					case ',':
148					case '<':
149						sb.append('_');
150						break;
151	
152					case '[':
153						sb.append('A');
154						break;
155	
156					case ']':
157					case '>':
158					case '?':
159					case '*':
160						break;
161	
162					default:
163						sb.append(c);
164						break;
165				}
166			}
167			return sb.toString();
168		}
