170		public static String escapeXML(String str) {
171			int len = str.length();
172			StringBuilder sb = new StringBuilder(len);
173			for (int i = 0; i < len; i++) {
174				char c = str.charAt(i);
175				String replace = escapeXmlChar(c);
176				if (replace != null) {
177					sb.append(replace);
178				} else {
179					sb.append(c);
180				}
181			}
182			return sb.toString();
183		}
184	
185		public static String escapeResValue(String str) {
186			int len = str.length();
187			StringBuilder sb = new StringBuilder(len);
188			for (int i = 0; i < len; i++) {
189				char c = str.charAt(i);
190				commonEscapeAndAppend(sb, c);
191			}
192			return sb.toString();
193		}
