195		public static String escapeResStrValue(String str) {
196			int len = str.length();
197			StringBuilder sb = new StringBuilder(len);
198			for (int i = 0; i < len; i++) {
199				char c = str.charAt(i);
200				switch (c) {
201					case '"':
202						sb.append("\\\"");
203						break;
204					case '\'':
205						sb.append("\\'");
206						break;
207					default:
208						commonEscapeAndAppend(sb, c);
209						break;
210				}
211			}
212			return sb.toString();
213		}
214	
215		private static @Nullable String escapeXmlChar(char c) {
216			if (c <= 0x1F) {
217				return "\\" + (int) c;
218			}
219			switch (c) {
220				case '&':
221					return "&amp;";
222				case '<':
223					return "&lt;";
224				case '>':
225					return "&gt;";
226				case '"':
227					return "&quot;";
228				case '\'':
229					return "&apos;";
230				case '\\':
231					return "\\\\";
232				default:
233					return null;
