10	import org.slf4j.Logger;
11	import org.slf4j.LoggerFactory;
12	
13	import jadx.core.Consts;
14	import jadx.core.dex.attributes.AType;
15	import jadx.core.dex.attributes.IAttributeNode;
16	import jadx.core.dex.attributes.nodes.JadxError;
17	import jadx.core.dex.nodes.IDexNode;
18	import jadx.core.dex.nodes.MethodNode;
19	import jadx.core.utils.exceptions.JadxOverflowException;
20	
21	public class ErrorsCounter {
22		private static final Logger LOG = LoggerFactory.getLogger(ErrorsCounter.class);
23		private static final boolean PRINT_MTH_SIZE = Consts.DEBUG;
24	
25		private final Set<IAttributeNode> errorNodes = new HashSet<>();
26		private int errorsCount;
27		private final Set<IAttributeNode> warnNodes = new HashSet<>();
28		private int warnsCount;
29	
30		public static <N extends IDexNode & IAttributeNode> String error(N node, String warnMsg, Throwable th) {
31			return node.root().getErrorsCounter().addError(node, warnMsg, th);
32		}
33	
34		public static <N extends IDexNode & IAttributeNode> void warning(N node, String warnMsg) {
35			node.root().getErrorsCounter().addWarning(node, warnMsg);
36		}
37	
38		public static String formatMsg(IDexNode node, String msg) {
39			return msg + " in " + node.typeName() + ": " + node + ", file: " + node.getInputFileName();
40		}
41	
42		private synchronized <N extends IDexNode & IAttributeNode> String addError(N node, String error, @Nullable Throwable e) {
43			errorNodes.add(node);
44			errorsCount++;
45	
46			String msg = formatMsg(node, error);
47			if (PRINT_MTH_SIZE && node instanceof MethodNode) {
48				String mthSize = "[" + ((MethodNode) node).getInsnsCount() + "] ";
49				msg = mthSize + msg;
50				error = mthSize + error;
51			}
52			if (e == null) {
53				LOG.error(msg);
54			} else if (e instanceof StackOverflowError) {
55				LOG.error("{}, error: StackOverflowError", msg);
56			} else if (e instanceof JadxOverflowException) {
57				// don't print full stack trace
58				String details = e.getMessage();
59				e = new JadxOverflowException(details);
60				if (details == null || details.isEmpty()) {
61					LOG.error("{}", msg);
62				} else {
63					LOG.error("{}, details: {}", msg, details);
64				}
65			} else {
66				LOG.error(msg, e);
67			}
68			node.addAttr(AType.JADX_ERROR, new JadxError(error, e));
69			return msg;
70		}
71	
72		private synchronized <N extends IDexNode & IAttributeNode> void addWarning(N node, String warn) {
73			warnNodes.add(node);
74			warnsCount++;
75			LOG.warn(formatMsg(node, warn));
76		}
77	
78		public void printReport() {
79			if (getErrorCount() > 0) {
80				LOG.error("{} errors occurred in following nodes:", getErrorCount());
81				List<String> errors = new ArrayList<>(errorNodes.size());
82				for (IAttributeNode node : errorNodes) {
83					String nodeName = node.getClass().getSimpleName().replace("Node", "");
84					errors.add(nodeName + ": " + node);
85				}
86				Collections.sort(errors);
87				for (String err : errors) {
88					LOG.error("  {}", err);
89				}
90			}
91			if (getWarnsCount() > 0) {
