		}

		String javaName;
		switch (descString) {
			case "void":
				javaName = "V";
				break;
			case "boolean":
				javaName = "Z";
				break;
			case "char":
				javaName = "C";
				break;
			case "byte":
				javaName = "B";
				break;
			case "short":
				javaName = "S";
