1	package jadx.core;
2	
3	import java.util.EnumMap;
4	import java.util.List;
5	import java.util.Map;
6	
7	import org.jetbrains.annotations.NotNull;
8	import org.jetbrains.annotations.Nullable;
9	import org.slf4j.Logger;
10	import org.slf4j.LoggerFactory;
11	
12	import jadx.api.DecompilationMode;
13	import jadx.api.ICodeInfo;
14	import jadx.api.JadxArgs;
15	import jadx.api.impl.SimpleCodeInfo;
16	import jadx.core.codegen.CodeGen;
17	import jadx.core.dex.attributes.AFlag;
18	import jadx.core.dex.attributes.AType;
19	import jadx.core.dex.attributes.nodes.DecompileModeOverrideAttr;
20	import jadx.core.dex.nodes.ClassNode;
21	import jadx.core.dex.nodes.LoadStage;
22	import jadx.core.dex.nodes.MethodNode;
23	import jadx.core.dex.nodes.RootNode;
24	import jadx.core.dex.visitors.DepthTraversal;
25	import jadx.core.dex.visitors.IDexTreeVisitor;
26	import jadx.core.utils.Utils;
27	import jadx.core.utils.exceptions.JadxRuntimeException;
28	
29	import static jadx.core.dex.nodes.ProcessState.GENERATED_AND_UNLOADED;
30	import static jadx.core.dex.nodes.ProcessState.LOADED;
31	import static jadx.core.dex.nodes.ProcessState.NOT_LOADED;
32	import static jadx.core.dex.nodes.ProcessState.PROCESS_COMPLETE;
33	import static jadx.core.dex.nodes.ProcessState.PROCESS_STARTED;
34	
35	public class ProcessClass {
36		private static final Logger LOG = LoggerFactory.getLogger(ProcessClass.class);
37	
38		private static final ICodeInfo NOT_GENERATED = new SimpleCodeInfo("");
39	
40		private final List<IDexTreeVisitor> passes;
41	
42		public ProcessClass(List<IDexTreeVisitor> passesList) {
43			this.passes = passesList;
44		}
45	
46		@Nullable
47		private ICodeInfo process(ClassNode cls, boolean codegen) {
48			if (!codegen && cls.getState() == PROCESS_COMPLETE) {
49				// nothing to do
50				return null;
51			}
52			Utils.checkThreadInterrupt();
53			synchronized (cls.getClassInfo()) {
54				try {
55					if (cls.contains(AFlag.CLASS_DEEP_RELOAD)) {
56						cls.remove(AFlag.CLASS_DEEP_RELOAD);
57						cls.deepUnload();
58						cls.add(AFlag.CLASS_UNLOADED);
59					}
60					if (cls.contains(AFlag.CLASS_UNLOADED)) {
61						cls.root().runPreDecompileStageForClass(cls);
62						cls.remove(AFlag.CLASS_UNLOADED);
63					}
64					if (cls.getState() == GENERATED_AND_UNLOADED) {
65						// force loading code again
66						cls.setState(NOT_LOADED);
67					}
68					if (codegen) {
69						cls.setLoadStage(LoadStage.CODEGEN_STAGE);
70						if (cls.contains(AFlag.RELOAD_AT_CODEGEN_STAGE)) {
71							cls.remove(AFlag.RELOAD_AT_CODEGEN_STAGE);
72							cls.unload();
73						}
74					} else {
75						cls.setLoadStage(LoadStage.PROCESS_STAGE);
76					}
77					if (cls.getState() == NOT_LOADED) {
78						cls.load();
79					}
80					if (cls.getState() == LOADED) {
81						cls.setState(PROCESS_STARTED);
82						for (IDexTreeVisitor visitor : passes) {
83							DepthTraversal.visit(visitor, cls);
84						}
85						cls.setState(PROCESS_COMPLETE);
86					}
87					if (codegen) {
88						Utils.checkThreadInterrupt();
89						ICodeInfo code = CodeGen.generate(cls);
90						if (!cls.contains(AFlag.DONT_UNLOAD_CLASS)) {
91							cls.unload();
92							cls.setState(GENERATED_AND_UNLOADED);
93						}
94						return code;
95					}
96					return null;
97				} catch (StackOverflowError | Exception e) {
98					if (codegen) {
99						throw e;
100					}
101					cls.addError("Class process error: " + e.getClass().getSimpleName(), e);
102					return null;
103				}
104			}
105		}
106	
107		@NotNull
108		public ICodeInfo generateCode(ClassNode cls) {
109			ClassNode topParentClass = cls.getTopParentClass();
110			if (topParentClass != cls) {
111				return generateCode(topParentClass);
112			}
113			try {
114				if (cls.contains(AFlag.DONT_GENERATE)) {
115					process(cls, false);
116					return NOT_GENERATED;
117				}
118				for (ClassNode depCls : cls.getDependencies()) {
119					process(depCls, false);
120				}
121				if (!cls.getCodegenDeps().isEmpty()) {
122					process(cls, false);
123					for (ClassNode codegenDep : cls.getCodegenDeps()) {
124						process(codegenDep, false);
125					}
126				}
127				ICodeInfo code = process(cls, true);
128				if (code == null) {
129					throw new JadxRuntimeException("Codegen failed");
130				}
131				return code;
132			} catch (StackOverflowError | Exception e) {
133				throw new JadxRuntimeException("Failed to generate code for class: " + cls.getFullName(), e);
134			}
135		}
136	
137		/**
138		 * Load and process class without its deps
139		 */
140		public void forceProcess(ClassNode cls) {
141			ClassNode topParentClass = cls.getTopParentClass();
142			if (topParentClass != cls) {
143				forceProcess(topParentClass);
144				return;
145			}
146			try {
147				process(cls, false);
148			} catch (StackOverflowError | Exception e) {
149				throw new JadxRuntimeException("Failed to process class: " + cls.getFullName(), e);
150			}
151		}
152	
153		/**
154		 * Generate code for class without processing its deps
155		 */
156		public @Nullable ICodeInfo forceGenerateCode(ClassNode cls) {
157			try {
158				return process(cls, true);
159			} catch (StackOverflowError | Exception e) {
160				throw new JadxRuntimeException("Failed to generate code for class: " + cls.getFullName(), e);
161			}
162		}
163	
164		private final Map<DecompilationMode, ProcessClass> modesMap = new EnumMap<>(DecompilationMode.class);
165	
166		public @Nullable ICodeInfo forceGenerateCodeForMode(ClassNode cls, DecompilationMode mode) {
167			synchronized (modesMap) {
168				ProcessClass prCls = modesMap.computeIfAbsent(mode, m -> {
169					RootNode root = cls.root();
170					ProcessClass newPrCls = new ProcessClass(getPassesForMode(root.getArgs(), m));
171					newPrCls.initPasses(root);
172					return newPrCls;
173				});
174				try {
175					cls.addAttr(new DecompileModeOverrideAttr(mode));
176					return prCls.forceGenerateCode(cls);
177				} finally {
178					cls.remove(AType.DECOMPILE_MODE_OVERRIDE);
179				}
180			}
181		}
182	
183		private static List<IDexTreeVisitor> getPassesForMode(JadxArgs baseArgs, DecompilationMode mode) {
184			switch (mode) {
185				case FALLBACK:
186					return Jadx.getFallbackPassesList();
187	
188				case SIMPLE:
189					// copy properties into new args
190					// keep in sync with properties usage in Jadx.getSimpleModePasses method
191					JadxArgs args = new JadxArgs();
192					args.setDebugInfo(baseArgs.isDebugInfo());
193					args.setCommentsLevel(baseArgs.getCommentsLevel());
194					return Jadx.getSimpleModePasses(args);
195	
196				default:
197					throw new JadxRuntimeException("Unexpected decompilation mode: " + mode);
198			}
