2	
3	import jadx.api.JadxArgs;
4	import jadx.api.deobf.IAliasProvider;
5	import jadx.api.deobf.IRenameCondition;
6	import jadx.core.dex.nodes.ClassNode;
7	import jadx.core.dex.nodes.FieldNode;
8	import jadx.core.dex.nodes.MethodNode;
9	import jadx.core.dex.nodes.PackageNode;
10	import jadx.core.dex.nodes.RootNode;
11	import jadx.core.dex.visitors.AbstractVisitor;
12	import jadx.core.utils.exceptions.JadxException;
13	
14	public class DeobfuscatorVisitor extends AbstractVisitor {
15	
16		@Override
17		public void init(RootNode root) throws JadxException {
18			JadxArgs args = root.getArgs();
19			if (!args.isDeobfuscationOn()) {
20				return;
21			}
22			DeobfPresets mapping = DeobfPresets.build(root);
23			if (args.getGeneratedRenamesMappingFileMode().shouldRead()) {
24				if (mapping.load()) {
25					mapping.apply(root);
26				}
27			}
28			IAliasProvider aliasProvider = args.getAliasProvider();
29			IRenameCondition renameCondition = args.getRenameCondition();
30			mapping.initIndexes(aliasProvider);
31			process(root, renameCondition, aliasProvider);
32		}
33	
34		public static void process(RootNode root, IRenameCondition renameCondition, IAliasProvider aliasProvider) {
35			boolean pkgUpdated = false;
36			for (PackageNode pkg : root.getPackages()) {
37				if (renameCondition.shouldRename(pkg)) {
38					String alias = aliasProvider.forPackage(pkg);
39					if (alias != null) {
40						pkg.rename(alias, false);
41						pkgUpdated = true;
42					}
43				}
44			}
45			if (pkgUpdated) {
46				root.runPackagesUpdate();
47			}
48	
49			for (ClassNode cls : root.getClasses()) {
50				if (renameCondition.shouldRename(cls)) {
51					String clsAlias = aliasProvider.forClass(cls);
52					if (clsAlias != null) {
53						cls.rename(clsAlias);
54					}
55				}
56				for (FieldNode fld : cls.getFields()) {
57					if (renameCondition.shouldRename(fld)) {
58						String fldAlias = aliasProvider.forField(fld);
59						if (fldAlias != null) {
60							fld.rename(fldAlias);
61						}
62					}
63				}
64				for (MethodNode mth : cls.getMethods()) {
65					if (renameCondition.shouldRename(mth)) {
66						String mthAlias = aliasProvider.forMethod(mth);
67						if (mthAlias != null) {
68							mth.rename(mthAlias);
69						}
70					}
71				}
72			}
73		}
74	
